            v = v * 10 + (p->s[p->pos] - '0');
            p->pos++;
        }
        return v;
    }
    if (!p->err) p->err = EVAL_SYNTAX;
    return 0;
}

static long parse_term(Parser *p) {
    long v = parse_primary(p);
    for (;;) {
        skip_ws(p);
        char c = p->s[p->pos];
        if (c != '*' && c != '/' && c != '%') return v;
