#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum EvalError {
    Syntax,
    DivByZero,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Err {
    None,
    Syntax,
    DivByZero,
}

struct Parser<'a> {
    /// Input bytes, truncated at the first NUL to mirror C string semantics.
    s: &'a [u8],
    pos: usize,
    err: Err,
}

impl Parser<'_> {
    /// Byte at `i`, or 0 (the C terminator) past the end.
    fn at(&self, i: usize) -> u8 {
        self.s.get(i).copied().unwrap_or(0)
    }

    fn set_err(&mut self, e: Err) {
        if self.err == Err::None {
            self.err = e;
        }
    }

    fn skip_ws(&mut self) {
        // C isspace in the "C" locale.
        while matches!(self.at(self.pos), b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
            self.pos += 1;
        }
    }

    fn parse_expr(&mut self) -> i64 {
        let mut v = self.parse_term();
        loop {
            self.skip_ws();
            let c = self.at(self.pos);
            if c != b'+' && c != b'-' {
                return v;
            }
            self.pos += 1;
            let r = self.parse_term();
            v = if c == b'+' { v.wrapping_add(r) } else { v.wrapping_sub(r) };
        }
    }

    fn parse_term(&mut self) -> i64 {
        let mut v = self.parse_primary();
        loop {
            self.skip_ws();
            let c = self.at(self.pos);
            if c != b'*' && c != b'/' && c != b'%' {
                return v;
            }
            self.pos += 1;
            let r = self.parse_primary();
            if c == b'*' {
                v = v.wrapping_mul(r);
            } else if r == 0 {
                self.set_err(Err::DivByZero);
                return 0;
            } else if c == b'/' {
                v = v.wrapping_div(r);
            } else {
                v = v.wrapping_rem(r);
            }
        }
    }

    fn parse_primary(&mut self) -> i64 {
        self.skip_ws();
        let c = self.at(self.pos);
        if c == b'(' {
            self.pos += 1;
            let v = self.parse_expr();
            self.skip_ws();
            if self.at(self.pos) != b')' {
                self.set_err(Err::Syntax);
                return 0;
            }
            self.pos += 1;
            return v;
        }
        if c == b'-' {
            self.pos += 1;
            return self.parse_primary().wrapping_neg();
        }
        if c.is_ascii_digit() {
            let mut v: i64 = 0;
            while self.at(self.pos).is_ascii_digit() {
                v = v
                    .wrapping_mul(10)
                    .wrapping_add(i64::from(self.at(self.pos) - b'0'));
                self.pos += 1;
            }
            return v;
        }
        self.set_err(Err::Syntax);
        0
    }
}

/// Evaluates an integer expression with + - * / % ( ) and unary minus.
/// Returns Ok(value), or Err((error, offset where parsing stopped)) with the same
/// error code and offset as the C version.
pub fn eval(s: &str) -> Result<i64, (EvalError, usize)> {
    let bytes = s.as_bytes();
    let end = bytes.iter().position(|&b| b == 0).unwrap_or(bytes.len());
    let mut p = Parser {
        s: &bytes[..end],
        pos: 0,
        err: Err::None,
    };
    let v = p.parse_expr();
    p.skip_ws();
    if p.err == Err::None && p.at(p.pos) != 0 {
        p.err = Err::Syntax;
    }
    match p.err {
        Err::None => Ok(v),
        Err::Syntax => Err((EvalError::Syntax, p.pos)),
        Err::DivByZero => Err((EvalError::DivByZero, p.pos)),
    }
}

